import Capacitor
import EscouadeMobileCore
import Foundation

/// MO-3: the mobile app's Rust (crates/escouade-mobile) under iOS, through the Swift bindings of UniFFI (generated by
/// scripts/mobile-ios.sh into ios/Sources/EscouadeMobileCore, the library in ios/escouade_mobileFFI.xcframework).
/// The API is src/definitions.ts; a failure rejects with the crate's error as the code (`Forged`, `BadKey`…).
@objc(EscouadeMobilePlugin)
public class EscouadeMobilePlugin: CAPPlugin, CAPBridgedPlugin {
    public let identifier = "EscouadeMobilePlugin"
    public let jsName = "EscouadeMobile"
    public let pluginMethods: [CAPPluginMethod] = [
        CAPPluginMethod(name: "startTunnel", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "tunnelStatus", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "stopTunnel", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "openNotification", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "version", returnType: CAPPluginReturnPromise),
    ]

    /// One tunnel per space.
    private var tunnels: [String: MobileTunnel] = [:]
    private let lock = NSLock()

    deinit {
        lock.lock()
        tunnels.values.forEach { $0.stop() }
        lock.unlock()
    }

    private func reject(_ call: CAPPluginCall, _ error: Error) {
        // The case's name (`Forged`, `BadKey`…) is the code, its text the message.
        let code = Mirror(reflecting: error).children.first?.label ?? "Io"
        let message = (error as? LocalizedError)?.errorDescription ?? "\(error)"
        call.reject(message, code)
    }

    private func stateName(_ state: MobileTunnelState) -> String {
        switch state {
        case .connecting: return "connecting"
        case .up: return "up"
        case .stopped: return "stopped"
        case .failed: return "failed"
        }
    }

    private func status(_ space: String, _ s: MobileTunnelStatus) -> [String: Any] {
        var o: [String: Any] = [
            "space": space,
            "state": stateName(s.state),
            "proxyUrl": s.proxyUrl,
            "websocketUrl": s.websocketUrl,
            "txBytes": Double(s.txBytes),
            "rxBytes": Double(s.rxBytes),
            "connections": Int(s.connections),
        ]
        if let h = s.lastHandshakeSecs { o["lastHandshakeSecs"] = Double(h) }
        if let e = s.error { o["error"] = e }
        return o
    }

    private func take(_ space: String) -> MobileTunnel? {
        lock.lock()
        defer { lock.unlock() }
        return tunnels.removeValue(forKey: space)
    }

    @objc func startTunnel(_ call: CAPPluginCall) {
        guard let space = call.getString("space") else { return call.reject("space is required", "BadConfig") }
        let keepalive = call.getInt("keepaliveSecs").map { UInt16(clamping: $0) }
        let config = MobileTunnelConfig(
            privateKey: call.getString("privateKey") ?? "",
            peerPublicKey: call.getString("peerPublicKey") ?? "",
            presharedKey: call.getString("presharedKey"),
            endpoint: call.getString("endpoint") ?? "",
            address: call.getString("address") ?? "",
            api: call.getString("api") ?? "",
            keepaliveSecs: keepalive
        )
        take(space)?.stop()
        do {
            let tunnel = try MobileTunnel.start(config: config)
            lock.lock()
            tunnels[space] = tunnel
            lock.unlock()
            call.resolve(status(space, tunnel.status()))
        } catch {
            reject(call, error)
        }
    }

    @objc func tunnelStatus(_ call: CAPPluginCall) {
        guard let space = call.getString("space") else { return call.reject("space is required", "BadConfig") }
        lock.lock()
        let tunnel = tunnels[space]
        lock.unlock()
        guard let tunnel else { return call.reject("no tunnel for this space", "NoTunnel") }
        call.resolve(status(space, tunnel.status()))
    }

    @objc func stopTunnel(_ call: CAPPluginCall) {
        guard let space = call.getString("space") else { return call.reject("space is required", "BadConfig") }
        take(space)?.stop()
        call.resolve()
    }

    @objc func openNotification(_ call: CAPPluginCall) {
        do {
            let n = try EscouadeMobileCore.openNotification(
                pairingKey: call.getString("pairingKey") ?? "",
                sealed: call.getString("sealed") ?? "",
                guardState: call.getString("guardState") ?? ""
            )
            var o: [String: Any] = [
                "seq": Double(n.seq),
                "at": Double(n.at),
                "kind": n.kind,
                "title": n.title,
                "body": n.body,
                "guardState": n.guardState,
            ]
            if let t = n.target { o["target"] = t }
            call.resolve(o)
        } catch {
            reject(call, error)
        }
    }

    @objc func version(_ call: CAPPluginCall) {
        call.resolve(["version": EscouadeMobileCore.mobileVersion()])
    }
}
